CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,phone TEXT NOT NULL UNIQUE,nickname TEXT NOT NULL,avatar_path TEXT,balance REAL NOT NULL DEFAULT 0 CHECK(balance>=0),status TEXT NOT NULL DEFAULT 'NORMAL',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'ADMIN',status TEXT NOT NULL DEFAULT 'NORMAL');
CREATE TABLE IF NOT EXISTS stations(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,address TEXT NOT NULL,longitude REAL NOT NULL,latitude REAL NOT NULL,base_price REAL NOT NULL DEFAULT 1.2,status TEXT NOT NULL DEFAULT 'ONLINE');
CREATE TABLE IF NOT EXISTS chargers(id INTEGER PRIMARY KEY AUTOINCREMENT,station_id INTEGER NOT NULL REFERENCES stations(id),code TEXT NOT NULL UNIQUE,type TEXT NOT NULL,rated_power REAL NOT NULL,status TEXT NOT NULL DEFAULT 'IDLE',last_seen TEXT,total_sessions INTEGER NOT NULL DEFAULT 0,total_duration INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reservations(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),charger_id INTEGER NOT NULL REFERENCES chargers(id),status TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,cancel_reason TEXT);
CREATE TABLE IF NOT EXISTS charge_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),charger_id INTEGER NOT NULL REFERENCES chargers(id),status TEXT NOT NULL,mode TEXT NOT NULL,target REAL NOT NULL,start_at TEXT NOT NULL,end_at TEXT,energy REAL NOT NULL DEFAULT 0,duration INTEGER NOT NULL DEFAULT 0,amount REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS telemetry(id INTEGER PRIMARY KEY AUTOINCREMENT,charger_id INTEGER NOT NULL REFERENCES chargers(id),order_id INTEGER REFERENCES charge_orders(id),sampled_at TEXT NOT NULL,voltage REAL,current REAL,power REAL,soc REAL,temperature REAL,energy_total REAL);
CREATE TABLE IF NOT EXISTS wallet_transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),type TEXT NOT NULL,amount REAL NOT NULL,balance_after REAL NOT NULL,related_order_id INTEGER REFERENCES charge_orders(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tariffs(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,energy_price REAL NOT NULL,service_price REAL NOT NULL,occupancy_price REAL NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS alarms(id INTEGER PRIMARY KEY AUTOINCREMENT,charger_id INTEGER REFERENCES chargers(id),level TEXT NOT NULL,type TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',created_at TEXT NOT NULL,resolved_at TEXT);
CREATE TABLE IF NOT EXISTS operation_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_type TEXT,actor_id INTEGER,action TEXT,target_type TEXT,target_id INTEGER,result TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_orders_user_status ON charge_orders(user_id,status);
CREATE INDEX IF NOT EXISTS idx_orders_charger_status ON charge_orders(charger_id,status);
CREATE INDEX IF NOT EXISTS idx_telemetry_charger_time ON telemetry(charger_id,sampled_at);
CREATE INDEX IF NOT EXISTS idx_reservation_expiry ON reservations(status,expires_at);

